&lt;p id=&quot;p-rc_15afc26ca3fee66b-412&quot; data-path-to-node=&quot;6,6,0&quot;&gt;&lt;span data-path-to-node=&quot;6,6,0,0&quot;&gt;Proven team leadership experience hiring&lt;span class=&quot;citation-7621 citation-end-7621&quot;&gt;, coaching, and developing talent across multiple regions and time zones&lt;/span&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;6,6,0,2&quot;&gt;&lt;span class=&quot;citation-7620 citation-end-7620&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
