&lt;/li&gt;
&lt;li&gt;
&lt;p id=&quot;p-rc_0a6b64f2e63d2ecc-67&quot; data-path-to-node=&quot;6,4,0&quot;&gt;&lt;span data-path-to-node=&quot;6,4,0,0&quot;&gt;Conduct privacy impact assessments and threat modeling for high-risk data processing activities&lt;/span&gt;&lt;span data-path-to-node=&quot;6,4,0,2&quot;&gt;.&lt;/span&gt;&lt;/p&gt;
