&lt;/li&gt;
&lt;li&gt;
&lt;p id=&quot;p-rc_52609cfc14722b46-72&quot; data-path-to-node=&quot;10,2,0&quot;&gt;&lt;span data-path-to-node=&quot;10,2,0,1&quot;&gt;&lt;span class=&quot;citation-89&quot;&gt;Translate customer pain points into practical solution designs and compelling business value narratives for Engineering leaders, Engineering managers, and cross-functional stakeholders&lt;/span&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;10,2,0,3&quot;&gt;.&lt;/span&gt;&lt;/p&gt;
